 d=document(a.raw);pos=[d['accessors'][p['attributes']['POSITION']]for m in d['meshes']for p in m['primitives']];lo=[min(v['min'][i]for v in pos)for i in range(3)];hi=[max(v['max'][i]for v in pos)for i in range(3)];bounds={'min':[lo[0],-hi[2],lo[1]],'max':[hi[0],-lo[2],hi[1]]};params=json.loads(Path(__file__).with_name('model-parameters.json').read_text());tool=subprocess.run([str(a.gltfpack),'-v'],capture_output=True,text=True)
 manifest={'id':ID,'model_id':ID,'name':'上海邮政总局历史主楼与钟塔','status':'original-photo-informed-exterior','viewer_page':'postal-office.html','audit_directory':'data/audit/postal-office-v1/','authored_bounds_enu_m':bounds,'outer_envelope_including_projection_design_estimate_m':dict(zip(['width','depth','height'],[bounds['max'][i]-bounds['min'][i]for i in range(3)])),'coordinate_convention':'author ENU metres; GLB east/up/south; heading0','anchor':params['anchor'],'model_scope_zh':params['scope'],'all_dimensions_estimated':True,'all_elevation_datums_estimated':True,'documented_existing_height_m':49.5,'documented_alternative_height_m':51.16,'height_conflict_preserved':True,'measured_survey':False,'selected_roof_levels_m':params['height_choice']['model_subdivision_estimate_m'],'documented_flagstaff_height_m':8.2,'clock_faces_modeled':1,'clock_orientation':'southeast chamfer only; side shoulders have small panels, no invented additional clocks','upper_tower_round_columns':8,'upper_tower_columns_smooth':True,'actual_open_upper_tower':True,'tower_cornice_has_plan_and_vertical_curvature':True,'statuary':{'groups':2,'figures_each':3,'geometry':'Original simplified seated/reclining figures, not exact cast/portrait reconstruction'},'top_main_gallery_depth_m':2.05,'north_facade_red_brick':True,'roof_small_objects':'Limited perimeter glass, two low service boxes and two low planters; exact layout estimated, not complete current rooftop','lettering':{'texts':['人民邮电','上海邮政博物馆'],'source':'Bundled renamed Noto Serif CJK SC subset under SIL OFL 1.1','typeface_photo_traced':False},'original_geometry':True,'geometry_license':'MIT','map_reference_license':'ODbL-1.0','bundled_font_software_license':'SIL OFL 1.1','photos_embedded':False,'third_party_models_embedded':False,'interiors_modeled':False,'underground_modeled':False,'site_slab_modeled':False,'courtyard_floor':{'z_m':[0,.16],'material':'dark stone','scope':'plain surface floor only, not structural collision; no exhibit or accessible interior reconstruction'},'courtyard_canopy':{'reference_photo_year':2010,'plan_and_span_estimated':True,'current_maintenance_state_verified':False,'glazing_alpha':.62,'closed_curved_end_glazing':True,'not_the_neighboring_source3148_barrel_roof':True},'adjacent_western_source3148_included':False,'city_integration':{'catalog':'data/candidate-city-integrations.json','id':ID,'view':'index.html#landmark='+ID+'&mode=overview','placement':'estimated','source_metadata_scope':'Only registered1959 main-source extent. Touching western source3148 and surrounding buildings retained; replacement/collision separately audited'},'complete_photo_reconstruction_accepted':False,'source_register':'source/precise/'+ID+'/source-register.json','source_candidate_metadata':d['extras'],'assets':assets,'packaging_tool':{'version_output':(tool.stdout+tool.stderr).strip(),'executable_sha256':hashlib.sha256(a.gltfpack.read_bytes()).hexdigest(),'flags':['-cc','-noq','-vnf','-km','-kn','-ke']}}
 (a.out/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n');print(json.dumps(assets,indent=2))
